// ═══ CONFIG ═══════════════════════════════════════════════════════
const CONFIG = {
  calendar_id:      'abdulrhman.a.otb@gmail.com', // '' or 'primary' = the account's default calendar
  timezone_offset:  '+03:00',                     // Saudi Arabia, no DST
  city:             'Riyadh',
  country:          'SA',
  prayer_method:    4,                            // 4 = Umm Al-Qura
  duration_minutes: 30,
  day_start_hour:   9,
  day_end_hour:     18,
  buffer_minutes:   10,                           // breathing room around existing meetings
  max_results:      12,
  days_to_scan:     5,
  skip_weekend:     true,                         // Friday + Saturday
};

// ── Read the tool's arguments, apply defaults, work out which days to scan ──
const raw = $input.first().json || {};
// When the tool is called with a free-text `query` instead of typed fields,
// try to read a JSON object out of it before falling back to defaults.
let p = raw;
if (typeof raw.query === 'string' && raw.query.trim().startsWith('{')) {
  try { p = Object.assign({}, raw, JSON.parse(raw.query)); } catch (e) { /* keep raw */ }
}
const val = (v, d) => (v === undefined || v === null || v === '' ) ? d : v;
const num = (v, d) => { if (v === undefined || v === null || v === '') return d; const n = Number(v); return Number.isFinite(n) ? n : d; };

const offset       = val(p.timezone_offset, CONFIG.timezone_offset);
const city         = val(p.city, CONFIG.city);
const country      = val(p.country, CONFIG.country);
const method       = num(p.prayer_method, CONFIG.prayer_method);          // 4 = Umm Al-Qura (KSA)
const calendarId   = val(p.calendar_id, CONFIG.calendar_id);
const duration     = num(p.duration_minutes, CONFIG.duration_minutes);
const dayStartHour = num(p.day_start_hour, CONFIG.day_start_hour);
const dayEndHour   = num(p.day_end_hour, CONFIG.day_end_hour);
const buffer       = num(p.buffer_minutes, CONFIG.buffer_minutes);
const maxResults   = num(p.max_results, CONFIG.max_results);
const skipWeekend  = val(p.skip_weekend, CONFIG.skip_weekend) !== false && val(p.skip_weekend, CONFIG.skip_weekend) !== 'false';

const pad = n => String(n).padStart(2, '0');
const offMin = (() => { const m = String(offset).match(/([+-])(\d{2}):?(\d{2})/); return m ? (m[1] === '-' ? -1 : 1) * (+m[2] * 60 + +m[3]) : 0; })();
const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;

const todayLocal = fmt(new Date(Date.now() + offMin * 60000));
const startDate  = /^\d{4}-\d{2}-\d{2}$/.test(String(p.date || '')) ? p.date : todayLocal;
const explicit   = /^\d{4}-\d{2}-\d{2}$/.test(String(p.date || ''));
// 0 (or missing) means "decide for me": one day when a date was named, a scan otherwise.
const asked      = num(p.days_to_scan, 0);
const scan       = asked > 0 ? Math.min(asked, 14) : (explicit ? 1 : CONFIG.days_to_scan);

const days = [];
let cur = Date.parse(startDate + 'T12:00:00Z');
let guard = 0;
while (days.length < scan && guard++ < 40) {
  const d = new Date(cur);
  const dow = d.getUTCDay();                       // 5 = Friday, 6 = Saturday
  const isWeekend = (dow === 5 || dow === 6);
  // A weekend day is skipped unless the caller named that exact date.
  if (!(skipWeekend && isWeekend && !(explicit && fmt(d) === startDate))) {
    days.push({ date: fmt(d), date_ddmmyyyy: `${pad(d.getUTCDate())}-${pad(d.getUTCMonth() + 1)}-${d.getUTCFullYear()}` });
  }
  cur += 86400000;
}

const rangeStart = days[0].date + 'T00:00:00' + offset;
const last = days[days.length - 1].date;
const rangeEnd = fmt(new Date(Date.parse(last + 'T12:00:00Z') + 86400000)) + 'T00:00:00' + offset;

return [{ json: {
  offset, city, country, method, calendarId,
  duration_minutes: duration, day_start_hour: dayStartHour, day_end_hour: dayEndHour,
  buffer_minutes: buffer, max_results: maxResults,
  attendee_emails: val(p.attendee_emails, ''),
  days, range_start: rangeStart, range_end: rangeEnd,
} }];

/* ── Prayer-aware availability engine ─────────────────────────────
   Pure function so it can be unit-tested outside n8n.            */

const PRAYERS = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
const DOW = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

function pad(n){ return String(n).padStart(2,'0'); }

// "04:12 (+03)" -> 252
function hhmmToMin(s){
  const m = String(s).match(/(\d{1,2}):(\d{2})/);
  return m ? (+m[1])*60 + (+m[2]) : null;
}
function minToHHMM(m){ return pad(Math.floor(m/60)) + ':' + pad(m%60); }
function iso(dateStr, min, offset){
  return `${dateStr}T${minToHHMM(((min%1440)+1440)%1440)}:00${offset}`;
}
// offset "+03:00" -> 180
function offsetMin(off){
  const m = String(off).match(/([+-])(\d{2}):?(\d{2})/);
  if(!m) return 0;
  return (m[1]==='-'?-1:1) * ((+m[2])*60 + (+m[3]));
}
// absolute instant -> {date:'YYYY-MM-DD', min:number} in the target offset
function toLocal(isoStr, off){
  const t = Date.parse(isoStr);
  if (Number.isNaN(t)) return null;
  const d = new Date(t + offsetMin(off)*60000);
  return {
    date: `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`,
    min: d.getUTCHours()*60 + d.getUTCMinutes(),
    abs: t,
  };
}
function dowOf(dateStr, off){
  return new Date(Date.parse(dateStr + 'T12:00:00' + off)).getUTCDay();
}
function mergeBlocks(blocks){
  const s = blocks.filter(b => b.end > b.start).sort((a,b)=> a.start-b.start);
  const out = [];
  for (const b of s){
    const last = out[out.length-1];
    if (last && b.start <= last.end){
      last.end = Math.max(last.end, b.end);
      if (last.labels.indexOf(b.label) === -1) last.labels.push(b.label);
    } else {
      out.push({start:b.start, end:b.end, labels:[b.label]});
    }
  }
  return out;
}

function computeAvailability(cfg){
  const {
    days,                       // ['YYYY-MM-DD', ...]
    offset = '+03:00',
    dayStartHour = 9,
    dayEndHour = 18,
    durationMinutes = 30,
    bufferMinutes = 10,
    granularity = 15,
    prayerBefore = 5,
    prayerAfter = 25,
    jumuahBefore = 45,
    jumuahAfter = 75,
    skipPrayers = [],           // e.g. ['Fajr','Isha'] if outside work hours anyway
    maxResults = 12,
    events = [],                // raw Google Calendar events
    prayerByDate = {},          // { 'YYYY-MM-DD': {Fajr:'04:12', ...} }
  } = cfg;

  const winStart = dayStartHour*60, winEnd = dayEndHour*60;
  const slots = [], report = [];

  for (const date of days){
    const dow = dowOf(date, offset);
    const blocks = [];

    // ── prayer blocks ──────────────────────────────────────────
    const timings = prayerByDate[date] || {};
    const prayerWindows = [];
    for (const p of PRAYERS){
      if (skipPrayers.indexOf(p) !== -1) continue;
      const t = hhmmToMin(timings[p]);
      if (t === null) continue;
      const isJumuah = (dow === 5 && p === 'Dhuhr');
      const b = t - (isJumuah ? jumuahBefore : prayerBefore);
      const e = t + (isJumuah ? jumuahAfter : prayerAfter);
      if (e <= winStart || b >= winEnd) continue;       // outside working hours
      const label = isJumuah ? 'Jumuah' : p;
      blocks.push({start:b, end:e, label});
      prayerWindows.push({name: label, adhan: minToHHMM(t), blocked: `${minToHHMM(Math.max(b,0))}–${minToHHMM(Math.min(e,1439))}`});
    }

    // ── calendar blocks ────────────────────────────────────────
    let allDay = null;
    for (const ev of events){
      if (!ev || ev.status === 'cancelled') continue;
      if (ev.transparency === 'transparent') continue;
      const me = (ev.attendees || []).find(a => a && a.self);
      if (me && me.responseStatus === 'declined') continue;

      if (ev.start && ev.start.date && !ev.start.dateTime){       // all-day
        const s = ev.start.date, e = ev.end && ev.end.date ? ev.end.date : s;
        if (date >= s && date < e){ allDay = ev.summary || 'All-day event'; }
        continue;
      }
      const s = toLocal(ev.start && ev.start.dateTime, offset);
      const e = toLocal(ev.end && ev.end.dateTime, offset);
      if (!s || !e) continue;
      let a = s.min, b = e.min;
      if (s.date !== date && e.date !== date) continue;
      if (s.date !== date) a = 0;                                  // spills in from previous day
      if (e.date !== date) b = 1440;                               // spills into next day
      blocks.push({start: a - bufferMinutes, end: b + bufferMinutes, label: ev.summary || 'Busy'});
    }

    if (allDay){
      report.push({date, weekday: DOW[dow], available: false, reason: `Blocked all day: ${allDay}`, prayer_windows: prayerWindows});
      continue;
    }

    const merged = mergeBlocks(blocks);
    const daySlots = [];
    let cursor = winStart;
    const gaps = [];
    for (const b of merged.concat([{start: winEnd, end: winEnd, labels:[]}])){
      if (b.start > cursor) gaps.push({start: cursor, end: Math.min(b.start, winEnd)});
      cursor = Math.max(cursor, b.end);
      if (cursor >= winEnd) break;
    }
    if (cursor < winEnd) gaps.push({start: cursor, end: winEnd});

    for (const g of gaps){
      let s = Math.ceil(Math.max(g.start, winStart)/granularity)*granularity;
      let taken = 0;
      while (s + durationMinutes <= Math.min(g.end, winEnd) && taken < 3){
        daySlots.push({
          date,
          weekday: DOW[dow],
          start: iso(date, s, offset),
          end: iso(date, s + durationMinutes, offset),
          local: `${minToHHMM(s)}–${minToHHMM(s+durationMinutes)}`,
        });
        s += Math.max(granularity, durationMinutes);
        taken++;
      }
    }

    report.push({
      date, weekday: DOW[dow],
      available: daySlots.length > 0,
      free_slots_found: daySlots.length,
      busy_blocks: merged.map(b => `${minToHHMM(Math.max(b.start,0))}–${minToHHMM(Math.min(b.end,1439))} (${b.labels.join(', ')})`),
      prayer_windows: prayerWindows,
    });
    slots.push(...daySlots);
  }

  return {
    duration_minutes: durationMinutes,
    working_hours: `${pad(dayStartHour)}:00–${pad(dayEndHour)}:00`,
    timezone_offset: offset,
    slots: slots.slice(0, maxResults),
    total_found: slots.length,
    days: report,
  };
}


// ── Wire n8n data into the engine ───────────────────────────────
const cfg = $('Prep Request').first().json;

const prayerByDate = {};
for (const item of $input.all()) {
  const d = item.json && item.json.data;
  if (!d || !d.timings) continue;
  const g = d.date && d.date.gregorian && d.date.gregorian.date;   // 'DD-MM-YYYY'
  if (!g) continue;
  const [dd, mm, yyyy] = g.split('-');
  prayerByDate[`${yyyy}-${mm}-${dd}`] = d.timings;
}

const events = $('Get Busy Events').all()
  .map(i => i.json)
  .filter(e => e && (e.start || e.id));

const result = computeAvailability({
  days: cfg.days.map(d => d.date),
  offset: cfg.offset,
  dayStartHour: cfg.day_start_hour,
  dayEndHour: cfg.day_end_hour,
  durationMinutes: cfg.duration_minutes,
  bufferMinutes: cfg.buffer_minutes,
  maxResults: cfg.max_results,
  events,
  prayerByDate,
});

result.calendar_id = cfg.calendarId;
result.instructions_for_the_assistant =
  'Offer the user 2-3 of these slots in plain language. Never invent a time that is not in "slots". ' +
  'When the user picks one, call book_meeting with that exact start and end value.';

return [{ json: result }];
